#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiChatMode: FfiConverterRustBuffer {
    typealias SwiftType = FfiChatMode

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiChatMode {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .chat
        
        case 2: return .task
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiChatMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case .chat:
            writeInt(&buf, Int32(1))
        
        
        case .task:
            writeInt(&buf, Int32(2))
        
        }
    }
}


