public enum PiyaError: Swift.Error {

    
    
    case Config(message: String
    )
    case Chat(message: String
    )
    case Mcp(message: String
    )
    case Queue(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePiyaError: FfiConverterRustBuffer {
    typealias SwiftType = PiyaError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PiyaError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Config(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Chat(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Mcp(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Queue(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PiyaError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Config(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Chat(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Mcp(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Queue(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypePiyaError_lift(_ buf: RustBuffer) throws -> PiyaError {
    return try FfiConverterTypePiyaError.lift(buf)
}

